head.script:
// 데이터/옵션 분리: JSON 은 순수 데이터만, 아래 type+옵션은 스크립트가 보유 → 렌더시 조합
scwin.CHART_TYPE = "barrange";                    // 차트 타입 (스크립트)
scwin.CHART_DATA_URL ="/ui/sample/SBChart/BARRANGE/data/BARRANGE.json";             // 순수 데이터 JSON (type 없음)
// ---- 차트 공통 상수 (SPCHART.md 회신 §1 일반화) ----
scwin.CHART_COLORS = ["#E52528", "#1B64DA", "#0A8060", "#F5A623", "#7B1FA2"];   // ★ 시리즈 색상 팔레트 — 현장 조정

scwin.CHART_CONFIG = {
  "color": { "pattern": scwin.CHART_COLORS },   // 시리즈 색상 명시 (미지정 시 라이브러리 기본색) — SPCHART.md §1-3
  "global": {   // 전역 설정(색/크기/애니메이션/이벤트)
    "size": {   // 차트 크기
      "width": 600   // 너비(px 또는 비율)
    }
  },
  "axis": {   // 축 설정
    "x": {
      "type": "category",   // 타입
      "categories": [   // 범주 목록
        "지하철",
        "버스",
        "택시",
        "따릉이",
        "도보",
        "기타 이동수단"
      ],
      "tick": {   // 눈금 설정
        "count": 6,   // 눈금 개수
        "outer": false,   // 바깥 눈금 표시
        "line": {   // 선 설정
          "show": false   // 표시 여부
        }
      }
    },
    "y": {
      "show": false,   // 표시 여부
      "domain": {   // 축 도메인(범위선)
        "show": false   // 표시 여부
      },
      "tick": {   // 눈금 설정
        "count": 6,   // 눈금 개수
        "line": {   // 선 설정
          "show": false   // 표시 여부
        },
        "values": [   // 눈금 값(배열)
          100000,
          400000,
          700000,
          1000000,
          1300000
        ],
        "outer": false   // 바깥 눈금 표시
      }
    }
  },
  "grid": {   // 격자선
    "x": {
      "show": false   // 표시 여부
    }
  },
  "extend": {   // 차트별 세부 옵션
    "barrange": {   // 바범위 전용 옵션
      "cornerRadius": 10,   // 모서리 둥글기
      "imageSetting": {   // 이미지 설정
        "useImages": true,   // 이미지 사용
        "imgW": 30,   // 이미지 폭
        "imgH": 30,   // 이미지 높이
        "moveX": 1   // X 이동
      }
    },
    "bar": {   // 막대 전용 옵션
      "width": {   // 너비(px 또는 비율)
        "ratio": 0.2   // 비율
      }
    }
  },
  "dataOpts": {   // 데이터 레벨 옵션(keys/labels 등)
    "keys": {   // 데이터 필드 매핑
      "x": "sub",
      "value": [   // 값 필드
        {
          "start": "DBP",   // 시작
          "end": "SBP"   // 끝
        }
      ]
    },
    "imageConf": [   // 이미지 매핑 설정
      {
        "src":"/ui/sample/SBChart/images/barrange1.png",   // 이미지 경로
        "rectColor": "#78B5E2"   // 배경 사각형 색
      },
      {
        "src":"/ui/sample/SBChart/images/barrange2.png",   // 이미지 경로
        "rectColor": "#78B5E2"   // 배경 사각형 색
      },
      {
        "src":"/ui/sample/SBChart/images/barrange3.png",   // 이미지 경로
        "rectColor": "#78B5E2"   // 배경 사각형 색
      },
      {
        "src":"/ui/sample/SBChart/images/barrange4.png",   // 이미지 경로
        "rectColor": "#78B5E2"   // 배경 사각형 색
      },
      {
        "src":"/ui/sample/SBChart/images/barrange5.png",   // 이미지 경로
        "rectColor": "#78B5E2"   // 배경 사각형 색
      },
      {
        "src":"/ui/sample/SBChart/images/barrange6.png",   // 이미지 경로
        "rectColor": "#78B5E2"   // 배경 사각형 색
      }
    ],
    "useLabelMultiLine": true,
    "useLabelOnBarrange": true,
    "useJsonColorForLabel": true,
    "labels": {   // 값 라벨 표시
      "format": function(value, id, index, ratio, originJson) {   // 표시 형식(포맷 함수)
        return "Max\n" + value + ' !!!';
      },
      "position": {   // 위치
        "y": -30
      }
    }
  }
};               // 옵션(global/axis/extend…) + dataOpts(keys/labels…)

/**
 * 차트 컨테이너를 정리한다. 재조회 렌더 전 호출 — 이전 차트 잔존 방지 (SPCHART.md §1-5)
 * (resize 리스너까지 해제하려면 sb.chart.render 직접 호출로 인스턴스를 잡아 sb.chart.destroy 사용)
 */
scwin.clearChart = function (comp) {
    const el = document.getElementById(comp.getID());
    if (el) { el.innerHTML = ""; }
};

scwin.onpageload = async function () {
    const res = await $c.sbm.executeDynamic({ id: "sbm_sbchart", action: scwin.CHART_DATA_URL, method: "get", mediatype: "application/json", mode: "asynchronous", isProcessMsg: false });
    const data = res.responseJSON;
    scwin.clearChart(chartWrap);   // 재조회 대비 이전 차트 정리
    $c.ext.drawChartData(scwin.CHART_TYPE, data, chartWrap, scwin.CHART_CONFIG);
};
